package android.net;public class Uri{String value;public Uri(String s){value=s;}public static Uri parse(String s){return new Uri(s);}public static Uri fromFile(java.io.File f){return new Uri("file:"+f.getPath());}public String getScheme(){return value.split(":")[0];}public String getHost(){return value.contains("://")?value.split("://")[1].split("/")[0]:null;}public String toString(){return value;}}